const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const sharp = require('sharp');
const {
  orientDevice,
  rotateFrame,
} = require('../.test-build/device-vision.js');
const { conclude } = require('../.test-build/inspection.js');
const { decodeBarcode } = require('../.test-build/barcode.js');
require('zxing-wasm/reader').prepareZXingModule({
  overrides: {
    wasmBinary: fs.readFileSync('public/barcode/zxing_reader.wasm'),
  },
});

// Aperture centres manually read from the supplied originals, not generated by
// the detector. b-8 is landscape; all others are 1280 × 1700.
const samples = {
  'b-1': [
    [590, 993],
    [642, 994],
    [546, 1255],
    [544, 1315],
  ],
  'b-2': [
    [548, 1182],
    [608, 1183],
    [490, 1497],
    [484, 1568],
  ],
  'b-3': [
    [419, 1055],
    [472, 1059],
    [366, 1307],
    [360, 1360],
  ],
  'b-5': [
    [656, 1080],
    [702, 1083],
    [617, 1315],
    [614, 1368],
  ],
  'b-7': [
    [639, 976],
    [690, 977],
    [595, 1230],
    [593, 1286],
  ],
  'b-8': [
    [912, 817],
    [958, 819],
    [878, 1027],
    [877, 1068],
  ],
};
async function pixels(name, size = 1024, brightness = 1, angle = 0) {
  const { data, info } = await sharp(`test-img/${name}.jpg`)
    .rotate(angle)
    .resize({
      width: size,
      height: size,
      fit: 'inside',
      withoutEnlargement: true,
    })
    .modulate({ brightness })
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  return {
    data: new Uint8ClampedArray(data),
    width: info.width,
    height: info.height,
  };
}
function pointsFor(name, frame) {
  const [w, h] = name === 'b-8' ? [1706, 1279] : [1280, 1700];
  return samples[name].map(([x, y]) => [
    (x * frame.width) / w,
    (y * frame.height) / h,
  ]);
}
function assertPositive(vision, context) {
  assert.equal(conclude(vision).code, 'positive', context);
  assert.deepEqual(
    vision.lamps.slice(0, 3).map((l) => l.state),
    ['off', 'on', 'off'],
    context,
  );
}
for (const name of Object.keys(samples)) {
  test(`${name}: adaptive apertures and real barcode decode from complete original`, async () => {
    const frame = await pixels(name);
    const started = performance.now();
    const oriented = orientDevice(frame);
    assert.equal(oriented.rotation, 0);
    assertPositive(oriented.vision, name);
    const points = pointsFor(name, frame);
    for (let i = 0; i < 3; i++) {
      const b = oriented.vision.lamps[i].box,
        [x, y] = points[i];
      assert.ok(
        x >= b.x && x <= b.x + b.width && y >= b.y && y <= b.y + b.height,
        `${name}: ${oriented.vision.lamps[i].key} box must contain the annotated physical aperture`,
      );
    }
    let code, scanSize;
    for (const size of [1536, 2560, 4096]) {
      const scan = await pixels(name, size),
        c = oriented.vision.cap;
      const sx = scan.width / frame.width,
        sy = scan.height / frame.height;
      code = await decodeBarcode(scan, {
        x: c.x * sx,
        y: c.y * sy,
        width: c.width * sx,
        height: c.height * sy,
      });
      scanSize = size;
      if (
        code.barcode ||
        code.ambiguous ||
        size >= (name === 'b-8' ? 1706 : 1700)
      )
        break;
    }
    assert.equal(code.barcode, '01202609030002');
    assert.equal(code.format, 'Code128');
    assert.equal(code.error, '');
    // Coordinates from the cropped retry must still point to the tube in the full image.
    assert.ok(
      code.box.y + code.box.height <
        oriented.vision.cap.y *
          (Math.min(scanSize, name === 'b-8' ? 1706 : 1700) / 1024),
    );
    fs.mkdirSync('test-output/bad-cases', { recursive: true });
    fs.writeFileSync(
      `test-output/bad-cases/${name}.json`,
      JSON.stringify(
        {
          vision: oriented.vision,
          code,
          scanSize,
          elapsedMs: Math.round(performance.now() - started),
        },
        null,
        2,
      ),
    );
  });
}
test('bad cases keep result across scale, exposure, mild tilt and right-angle rotations', async () => {
  for (const name of Object.keys(samples)) {
    for (const [size, brightness, angle] of [
      [768, 1, 0],
      [1536, 1, 0],
      [1024, 0.65, 0],
      [1024, 1.2, 0],
      [1024, 1, 5],
      [1024, 1, -5],
    ]) {
      const r = orientDevice(await pixels(name, size, brightness, angle));
      assert.equal(r.rotation, 0, `${name}, ${size}, ${brightness}, ${angle}`);
      assertPositive(r.vision, `${name}, ${size}, ${brightness}, ${angle}`);
    }
    const frame = await pixels(name);
    for (const angle of [90, 180, 270]) {
      const r = orientDevice(rotateFrame(frame, angle));
      assert.equal((r.rotation + angle) % 360, 0, name);
      assertPositive(r.vision, `${name}, rotation ${angle}`);
    }
  }
});
test('Power pixel brightness cannot change result states or be selected as Invalid', async () => {
  for (const name of Object.keys(samples)) {
    const original = await pixels(name),
      [px, py] = pointsFor(name, original)[3];
    const baseline = orientDevice(original).vision;
    for (const color of [
      [10, 10, 10],
      [255, 30, 30],
      [255, 220, 30],
    ]) {
      const frame = { ...original, data: original.data.slice() };
      for (let y = Math.round(py) - 5; y <= py + 5; y++)
        for (let x = Math.round(px) - 5; x <= px + 5; x++)
          if (Math.hypot(x - px, y - py) <= 5)
            frame.data.set([...color, 255], (y * frame.width + x) * 4);
      const actual = orientDevice(frame).vision;
      assert.deepEqual(
        actual.lamps.slice(0, 3).map((l) => [l.state, l.color]),
        baseline.lamps.slice(0, 3).map((l) => [l.state, l.color]),
        name,
      );
      assert.deepEqual(conclude(actual), conclude(baseline), name);
      for (let i = 0; i < 3; i++) {
        const b = actual.lamps[i].box,
          [x, y] = pointsFor(name, frame)[i];
        assert.ok(
          x >= b.x && x <= b.x + b.width && y >= b.y && y <= b.y + b.height,
          `${name}: result aperture ${i}`,
        );
      }
    }
  }
});

test('adaptive positioning follows synthetic Negative and Invalid lamps rather than assuming Positive', async () => {
  for (const name of Object.keys(samples)) {
    const original = await pixels(name),
      points = pointsFor(name, original);
    for (const target of [-1, 0, 2]) {
      const frame = { ...original, data: original.data.slice() };
      // Replace only the Positive aperture with the neighbouring unlit aperture.
      const [nx, ny] = points[0].map(Math.round),
        [px, py] = points[1].map(Math.round);
      for (let dy = -10; dy <= 10; dy++)
        for (let dx = -10; dx <= 10; dx++) {
          const src = ((ny + dy) * frame.width + nx + dx) * 4;
          frame.data.set(
            original.data.subarray(src, src + 4),
            ((py + dy) * frame.width + px + dx) * 4,
          );
        }
      if (target >= 0) {
        const [cx, cy] = points[target];
        for (let y = Math.round(cy) - 5; y <= cy + 5; y++)
          for (let x = Math.round(cx) - 5; x <= cx + 5; x++)
            if (Math.hypot(x - cx, y - cy) <= 5)
              frame.data.set([255, 70, 40, 255], (y * frame.width + x) * 4);
      }
      const result = orientDevice(frame).vision;
      assert.equal(
        conclude(result).code,
        target === -1 ? 'unknown' : target === 0 ? 'negative' : 'invalid',
        `${name}, target ${target}`,
      );
    }
  }
});
